import json
import math
import adapter_kit


def adapt(path):
    try:
        coords = adapter_kit.read_coordinates(path)
    except Exception as exc:
        return {"text": "Could not read coordinates: " + str(exc)}

    lines = ["Coordinate count: %d" % len(coords)]
    for i, pair in enumerate(coords[:10], 1):
        try:
            lat, lon = pair
            lat, lon = float(lat), float(lon)
            lines.append("Coordinate %d: latitude %.8f, longitude %.8f" % (i, lat, lon))
            if not (math.isfinite(lat) and math.isfinite(lon)):
                continue
            try:
                summary = adapter_kit.coordinate_summary(lat, lon)
                lines.append("Geographic context: " + json.dumps(summary, ensure_ascii=False, default=str))
            except Exception:
                pass
            try:
                places = adapter_kit.nearest_places(lat, lon)
                lines.append("Nearby places: " + json.dumps(places, ensure_ascii=False, default=str))
            except Exception:
                pass
        except Exception:
            lines.append("Coordinate %d: %s" % (i, str(pair)))
    return {"text": "\n".join(lines)[:4000]}
